import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.textfield.TextField;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest
class ItemsViewTest extends SpringBrowserlessTest {

    private TextField itemField;
    private Button addButton;
    private Button clearButton;
    private Span countLabel;

    @BeforeEach
    void setUp() {
        navigate(ItemsView.class);
        itemField = $(TextField.class).first();
        addButton = $(Button.class).all().get(0);
        clearButton = $(Button.class).all().get(1);
        countLabel = $(Span.class).first();
    }

    private void add(String value) {
        itemField.setValue(value);
        test(addButton).clickInServer();
    }

    @Test
    void addAppendsItemAndClearsField() {
        add("First");
        add("Second");
        add("First");

        var items = $(ListItem.class).all();
        assertEquals(3, items.size());
        assertEquals("First", items.get(0).getText());
        assertEquals("Second", items.get(1).getText());
        assertEquals("First", items.get(2).getText());
        assertEquals("", itemField.getValue());
        assertEquals("Items: 3", countLabel.getText());
    }

    @Test
    void blankAddIsRejected() {
        add("");
        add("   ");

        assertEquals(0, $(ListItem.class).all().size());
        assertEquals("Items: 0", countLabel.getText());
        assertTrue(itemField.isInvalid());
    }

    @Test
    void clearRemovesEverythingAndItemsCanBeAddedAgain() {
        add("One");
        add("Two");
        test(clearButton).clickInServer();

        assertEquals(0, $(ListItem.class).all().size());
        assertEquals("Items: 0", countLabel.getText());

        add("Three");
        assertEquals(1, $(ListItem.class).all().size());
        assertEquals("Items: 1", countLabel.getText());
        assertFalse(itemField.isInvalid());
    }
}
